import {simulationDefaults,simulateCurrent,empiricalCDF} from './simulation.js';
import {reducedMotion} from './motion.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString('en-US',{maximumFractionDigits:d}):'—';
const configs=new Map();
const labels={growth:['Revenue growth',100,'%'],targetMargin:['Mature margin',100,'%'],salesCapital:['Sales / capital',1,'×'],wacc:['Cost of capital',100,'%']};
const signal=()=>globalThis.matchMedia?.('(prefers-reduced-motion: reduce)');
const palettes={forest:['#d4ef8b','#142d27','#f7faee'],slate:['#b5caff','#142640','#f5f7ff'],midnight:['#a4e5ce','#0b121d','#edf2fa'],sand:['#f6ca88','#432a20','#fff8eb'],plum:['#ecb7e3','#322039','#fff4fd'],ocean:['#afe6e5','#123641','#f0fffd']};
const palette=()=>{const [signal,stage,text]=palettes[globalThis.document?.documentElement?.dataset?.theme]||palettes.forest;return {signal,stage,text}};
const dimensions={width:960,height:390,left:48,right:918,top:76,bottom:326};
export function mountSimulation(root,snapshot,draft){
 if(!root)return ()=>{};
 const key=JSON.stringify([snapshot.ticker,snapshot.raw?.id,snapshot.periodEnd,draft.assumptions,draft.normalizationDelta]);
 let barFinals=[];
 let config=structuredClone(configs.get(key)||simulationDefaults(draft.assumptions)),result,animations=[],cleanups=[],destroyed=false,selected,paused=false,viewed=false;
 const find=s=>root.querySelector(s);
 const listen=(target,type,fn,opts)=>{target?.addEventListener?.(type,fn,opts);cleanups.push(()=>target?.removeEventListener?.(type,fn,opts))};
 const finish=()=>{animations.forEach(a=>{try{a.cancel()}catch{}});animations=[];barFinals.forEach(({node,height})=>{node?.setAttribute('height',height);node?.setAttribute('y',dimensions.bottom-height)});find('#mc-animation-status')&&(find('#mc-animation-status').textContent='Full distribution · all accepted scenarios');if(find('#mc-skip'))find('#mc-skip').hidden=true;find('#mc-particles')?.replaceChildren();const b=find('#mc-play');if(b){b.textContent='Replay the flow ↻';b.setAttribute('aria-pressed','false')}paused=false;};
 const destroy=()=>{destroyed=true;finish();cleanups.forEach(fn=>fn());cleanups=[];};
 function shell(){root.innerHTML=`<section class="simulation-lab" aria-labelledby="mc-title"><div class="mc-heading"><div><p class="eyebrow">THE POSSIBILITY ENGINE</p><h3 id="mc-title">A range of futures.<br><em>A clearer perspective.</em></h3></div><span class="mc-count">MONTE CARLO<br><b>4,000</b> SCENARIOS</span></div><p class="mc-intro">One story can unfold in many ways. Vary four assumptions and watch the conditional values take shape.</p><div id="mc-output"></div><details class="mc-settings"><summary>Shape the uncertainty <span>Four editable ranges ↗</span></summary><p class="micro">Illustrative triangular distributions, not market-calibrated probabilities. Low and high are bounds; mode is the most likely input within your chosen range. Review every range before relying on the output.</p><div class="mc-input-grid">${Object.entries(labels).map(([k,[name,scale,unit]])=>`<fieldset><legend>${name} · ${unit}</legend>${['low','mode','high'].map(part=>`<label for="mc-${k}-${part}">${{low:'Low',mode:'Mode',high:'High'}[part]}<input id="mc-${k}-${part}" data-mc-driver="${k}" data-mc-part="${part}" type="number" step="${scale===100?'.1':'.05'}" value="${fmt(config.drivers[k][part]*scale,4).replaceAll(',','')}" inputmode="decimal"></label>`).join('')}</fieldset>`).join('')}</div><div class="mc-settings-row"><label for="mc-dependence">Driver relationships<select id="mc-dependence"><option value="independent" ${config.dependence==='independent'?'selected':''}>Independent assumptions</option><option value="operating-linked" ${config.dependence==='operating-linked'?'selected':''}>Operating-linked assumptions</option></select></label><label for="mc-seed">Reproducible seed<input id="mc-seed" type="text" maxlength="80" value="${esc(String(config.seed))}"></label></div><p class="micro">Tax, stable growth, marginal ROIC, financial claims and share count remain fixed. Both relationship choices are modeling assumptions. They have not been calibrated to this company.</p><button id="mc-run" class="primary">Run 4,000 scenarios <span aria-hidden="true">↗</span></button><p id="mc-error" role="status" class="micro"></p></details><div class="mc-bottom"><p id="mc-audit" class="micro"></p><a href="./data/simulation-methodology.html" target="_blank" rel="noopener">How this simulation works ↗</a><button id="mc-export" class="text-button">Export simulation ↓</button></div></section>`;
 find('#mc-run').onclick=()=>{const next=structuredClone(config);root.querySelectorAll('[data-mc-driver]').forEach(el=>{const scale=labels[el.dataset.mcDriver][1];next.drivers[el.dataset.mcDriver][el.dataset.mcPart]=el.value.trim()===''?NaN:Number(el.value)/scale});next.dependence=find('#mc-dependence').value;next.seed=find('#mc-seed').value;try{const r=simulateCurrent(snapshot,draft,next);config=next;result=r;configs.set(key,structuredClone(config));find('#mc-error').textContent='';paint();play();}catch(e){finish();result=null;find('#mc-output').innerHTML='<div class="error" role="status">Simulation withheld. The edited ranges are invalid; correct them and run again.</div>';find('#mc-audit').textContent='No current simulation result.';find('#mc-error').textContent=e.message;}};
 find('#mc-export').onclick=()=>{if(!result)return;const blob=new Blob([JSON.stringify({classification:'User-assumed conditional Monte Carlo; not calibrated probabilities or a forecast of market price.',snapshotId:snapshot.raw?.id,snapshot:structuredClone(snapshot),draft:structuredClone(draft),ticker:snapshot.ticker,sourcePeriod:snapshot.periodEnd,quote:draft.quote,...result},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${snapshot.ticker}-conditional-simulation.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
 }
 function domain(){const values=result.samples,min=values[0],max=values.at(-1);let lo=min,hi=max;if(min===max){const pad=Math.max(Math.abs(min)*.12,1);lo=Math.max(0,min-pad);hi=max+pad}return [lo,hi];}
 function plotX(value){const [lo,hi]=domain();return dimensions.left+(Math.max(lo,Math.min(hi,value))-lo)/(hi-lo)*(dimensions.right-dimensions.left);}
 function inspect(value,label='Inspected value',allowOutside=false){
  if(!result?.accepted)return;const [lo,hi]=domain();selected=Math.max(lo,Math.min(hi,value));value=allowOutside?value:selected;const chart=find('#mc-chart');
  find('#mc-inspector').innerHTML=`<span>${esc(label)}</span><b>${fmt(value)} <small>${esc(snapshot.currency)} / share</small></b><span>${fmt(empiricalCDF(result.samples,value)*100,1)}th percentile <small>· ${fmt(empiricalCDF(result.samples,value)*100,1)}% of simulated values at or below · includes ties</small></span>`;
  chart?.setAttribute('aria-valuenow',String(selected));chart?.setAttribute('aria-valuetext',`${fmt(value)} ${snapshot.currency} per share, ${fmt(empiricalCDF(result.samples,value)*100,1)} percentile of simulated values`);
  const line=find('#mc-inspect-line');line?.setAttribute('x1',plotX(selected));line?.setAttribute('x2',plotX(selected));const circle=find('#mc-inspect-dot');circle?.setAttribute('cx',plotX(selected));const range=find('#mc-scrubber');if(range){range.value=String((selected-lo)/(hi-lo)*1000);range.setAttribute('aria-valuetext',`${fmt(selected)} ${snapshot.currency} per share; ${fmt(empiricalCDF(result.samples,selected)*100,1)}% of simulated values at or below`);}
 }
 function paint(){
  finish();const out=find('#mc-output');
  if(!result.accepted){out.innerHTML='<div class="error">No valid scenarios. Review the input ranges and model constraints, especially WACC versus stable growth.</div>';find('#mc-audit').textContent=`${fmt(result.attempts,0)} attempted · ${fmt(result.excluded,0)} excluded (${Object.entries(result.exclusions).map(([reason,n])=>reason+': '+n).join(', ')}). No histogram or percentiles available.`;return;}
  const colors=palette();const [lo,hi]=domain(),{left,right,bottom,top}=dimensions,maxCount=Math.max(...result.histogram.map(b=>b.count)),q=result.quote,medianX=plotX(result.median),marketX=q.status==='ready'?plotX(q.price):null;
  out.innerHTML=`<div class="mc-stat-row"><button id="mc-median" class="mc-stat" aria-label="Inspect simulated median"><span><i class="mc-dot median"></i> Simulated median</span><b>${fmt(result.median)} <small>${esc(snapshot.currency)}</small></b><small>50th percentile · ${fmt(result.quantiles.p10)}–${fmt(result.quantiles.p90)} central 80%</small></button><button id="mc-market" class="mc-stat ${q.status==='ready'?'':'is-missing'}" aria-label="${q.status==='ready'?'Inspect dated market price':'Add a sourced market quote'}"><span><i class="mc-dot market"></i> ${q.status==='ready'?'Dated market price':'Market price'}</span><b>${q.status==='ready'?fmt(q.price):'Add a quote'} <small>${q.status==='ready'?esc(snapshot.currency):'↓'}</small></b><small>${q.status==='ready'?`${fmt(q.percentile,1)}th percentile · ${esc(q.date)}`:'Enter a sourced quote below to compare'}</small></button></div><div class="mc-chart-wrap"><div class="mc-chart-top"><span id="mc-animation-status">Full distribution · all accepted scenarios</span><div class="mc-playback"><button id="mc-skip" hidden>Show full chart</button><button id="mc-play" aria-pressed="false">Replay the flow ↻</button></div></div><div id="mc-chart" class="mc-chart" role="slider" tabindex="0" aria-label="Inspect conditional valuation distribution" aria-valuemin="${lo}" aria-valuemax="${hi}" aria-valuenow="${result.median}" aria-describedby="mc-help"><svg viewBox="0 0 960 420" aria-hidden="true"><defs><linearGradient id="mc-bar-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="${colors.signal}" stop-opacity=".96"/><stop offset="1" stop-color="${colors.signal}" stop-opacity=".28"/></linearGradient></defs>${[0,.25,.5,.75,1].map(t=>`<line x1="${left}" x2="${right}" y1="${bottom-(bottom-top)*t}" y2="${bottom-(bottom-top)*t}" stroke="white" stroke-opacity=".08"/>`).join('')}<text x="${left}" y="37" class="mc-svg-note" style="fill:${colors.text}">SHARE OF ACCEPTED SCENARIOS</text>${[.5,1].map(t=>`<text x="${right}" y="${bottom-(bottom-top)*t-9}" text-anchor="end" class="mc-svg-note" style="fill:${colors.text}">${fmt(maxCount/result.accepted*t*100,1)}%</text>`).join('')}<g id="mc-bars">${result.histogram.map((bin,i)=>{const x=result.histogram.length===1?plotX(result.median)-12:plotX(bin.low),width=result.histogram.length===1?24:Math.max(2,plotX(bin.high)-x-3),height=bin.count/maxCount*(bottom-top);return `<rect class="mc-bin" data-bin="${i}" x="${x}" y="${bottom-height}" width="${width}" height="${height}" rx="3" fill="${colors.signal}" fill-opacity=".78"/>`}).join('')}</g><g id="mc-particles"></g><line x1="${medianX}" x2="${medianX}" y1="58" y2="${bottom}" stroke="white" stroke-width="1.5" stroke-dasharray="4 5"/><rect x="${Math.max(left,Math.min(right-74,medianX-37))}" y="42" width="74" height="23" rx="11" fill="white"/><text x="${Math.max(left+37,Math.min(right-37,medianX))}" y="57" text-anchor="middle" class="mc-marker-label" fill="${colors.stage}">P50</text>${q.status==='ready'?`<line x1="${marketX}" x2="${marketX}" y1="80" y2="${bottom}" stroke="${colors.signal}" stroke-width="2"/><circle cx="${marketX}" cy="${bottom}" r="5" fill="${colors.signal}"/>`:''}<line id="mc-inspect-line" x1="${medianX}" x2="${medianX}" y1="72" y2="${bottom}" stroke="white" stroke-opacity=".4"/><circle id="mc-inspect-dot" cx="${medianX}" cy="${bottom}" r="5" fill="white"/>${[0,.25,.5,.75,1].map((p,i)=>`<text x="${left+(right-left)*p}" y="358" text-anchor="${i===0?'start':i===4?'end':'middle'}" class="mc-axis-label ${i===1||i===3?'mc-axis-intermediate':''}" style="fill:${colors.text}">${fmt(lo+(hi-lo)*p,hi<20?1:0)}</text>`).join('')}<text x="480" y="403" text-anchor="middle" class="mc-svg-note" style="fill:${colors.text}">${esc(snapshot.currency)} PER ECONOMIC SHARE</text></svg></div><div id="mc-inspector" class="mc-inspector" aria-live="polite" aria-atomic="true"></div><label class="mc-scrubber-label" for="mc-scrubber">Explore the distribution<input id="mc-scrubber" type="range" min="0" max="1000" step="1" value="500" aria-label="Explore simulated value"></label><p id="mc-help" class="mc-help">Hover, tap or drag to inspect. Keyboard: ← → to explore, Home / End for bounds. Median and market-price cards jump to each marker.</p></div><p class="mc-quote-note">${q.status==='ready'?`Your entered quote: ${fmt(q.price)} ${esc(snapshot.currency)} on ${esc(q.date)} · <a href="${esc(draft.quote.sourceUrl)}" target="_blank" rel="noopener">quote source ↗</a>. ${q.price<lo||q.price>hi?'Market-price marker is pinned to the nearest chart edge. ':''}${fmt(q.percentile,1)}% of accepted simulated values are at or below that price. This is not a probability of a future market-price move.`:esc(q.message)+' No live quote feed is connected.'}</p><details class="mc-table"><summary>View exact distribution & percentile table</summary><div class="table-wrap"><table><caption>Conditional per-share values · ${esc(snapshot.currency)}</caption><thead><tr><th scope="col">Percentile</th><th scope="col">Value / share</th></tr></thead><tbody>${Object.entries(result.quantiles).map(([k,v])=>`<tr><th scope="row">${k.slice(1)}th</th><td>${fmt(v)}</td></tr>`).join('')}</tbody></table><table><caption>Histogram · all accepted scenarios</caption><thead><tr><th scope="col">Value range</th><th scope="col">Scenarios</th><th scope="col">Share</th></tr></thead><tbody>${result.histogram.map(b=>`<tr><th scope="row">${fmt(b.low)}–${fmt(b.high)}</th><td>${b.count}</td><td>${fmt(b.share*100,2)}%</td></tr>`).join('')}</tbody></table></div></details>`;
  barFinals=result.histogram.map((b,i)=>({node:root.querySelector(`[data-bin="${i}"]`),height:b.count/maxCount*(bottom-top)}));
  const chart=find('#mc-chart');let dragging=false;
  function pointer(e){const box=chart.getBoundingClientRect();if(!box.width)return;const x=(e.clientX-box.left)/box.width*960;inspect(lo+Math.max(0,Math.min(1,(x-left)/(right-left)))*(hi-lo));}
  chart.onpointermove=e=>{if(e.pointerType==='mouse'||dragging)pointer(e)};chart.onpointerdown=e=>{dragging=true;pointer(e);try{chart.setPointerCapture?.(e.pointerId)}catch{}};chart.onpointerup=chart.onpointercancel=e=>{dragging=false;try{chart.releasePointerCapture?.(e.pointerId)}catch{}};
  chart.onkeydown=e=>{let value=selected,delta=(hi-lo)/(e.shiftKey?20:100);if(e.key==='ArrowRight'||e.key==='ArrowUp')value+=delta;else if(e.key==='ArrowLeft'||e.key==='ArrowDown')value-=delta;else if(e.key==='Home')value=lo;else if(e.key==='End')value=hi;else return;e.preventDefault();inspect(value)};
  find('#mc-skip').onclick=()=>finish();find('#mc-scrubber').oninput=e=>inspect(lo+Number(e.target.value)/1000*(hi-lo));find('#mc-median').onclick=()=>inspect(result.median,'Simulated median');find('#mc-median').onpointerenter=()=>inspect(result.median,'Simulated median');find('#mc-median').onfocus=()=>inspect(result.median,'Simulated median');find('#mc-market').onpointerenter=()=>{if(q.status==='ready')inspect(q.price,`Dated market price · ${q.date}`,true)};find('#mc-market').onfocus=()=>{if(q.status==='ready')inspect(q.price,`Dated market price · ${q.date}`,true)};find('#mc-market').onclick=()=>{if(q.status==='ready')inspect(q.price,`Dated market price · ${q.date}`,true);else{const form=document.querySelector('#market-quote');if(form){form.open=true;form.scrollIntoView({block:'start',behavior:reducedMotion()?'auto':'smooth'});document.querySelector('#quote-price')?.focus({preventScroll:true})}}};find('#mc-play').onclick=()=>{if(animations.length){if(paused){animations.forEach(a=>a.play());paused=false;find('#mc-play').textContent='Pause the flow Ⅱ';find('#mc-play').setAttribute('aria-pressed','true')}else{animations.forEach(a=>a.pause());paused=true;find('#mc-play').textContent='Resume the flow ▷';find('#mc-play').setAttribute('aria-pressed','false')}}else play()};
  find('#mc-audit').textContent=`${fmt(result.attempts,0)} attempted · ${fmt(result.accepted,0)} accepted · ${fmt(result.excluded,0)} excluded${result.excluded?' ('+Object.entries(result.exclusions).map(([reason,n])=>reason+': '+n).join(', ')+')':''} · ${fmt(result.zeroEquityCount,0)} zero-equity outcomes. ${result.dependence?.description||''} Visual particles are a representative subset; histogram and percentiles use every accepted scenario.`;
  inspect(result.median,'Simulated median');
 }
 function play(){
  finish();if(destroyed||!result?.accepted||reducedMotion()||typeof document.createElementNS!=='function'){const b=find('#mc-play');if(b&&reducedMotion()){b.textContent='Reduced motion · static view';b.disabled=true}return;}
  const group=find('#mc-particles');if(!group)return;const count=globalThis.matchMedia?.('(max-width: 600px)').matches?64:112,maxCount=Math.max(...result.histogram.map(b=>b.count)),nonempty=result.histogram.filter(b=>b.count>0).length;
  const quotas=result.histogram.map(b=>b.count>0?1+Math.floor((count-nonempty)*b.share):0);let remaining=count-quotas.reduce((a,b)=>a+b,0);const order=result.histogram.map((b,i)=>({i,f:(count-nonempty)*b.share%1})).filter(({i})=>quotas[i]>0).sort((a,b)=>b.f-a.f);for(let i=0;i<remaining;i++)quotas[order[i%order.length].i]++;
  const representatives=[];result.histogram.forEach((bin,bi)=>{const values=result.samples.filter(v=>v>=bin.low&&(bi===result.histogram.length-1?v<=bin.high:v<bin.high));for(let j=0;j<quotas[bi];j++)representatives.push({bi,value:values[Math.min(values.length-1,Math.floor((j+.5)/quotas[bi]*values.length))]??bin.low})});
  representatives.sort((a,b)=>((a.value*1009)%997)-((b.value*1009)%997));const arrivals=quotas.map(()=>0),scheduled=quotas.map(()=>0);
  barFinals.forEach(({node})=>{node?.setAttribute('height','0');node?.setAttribute('y',dimensions.bottom)});find('#mc-animation-status').textContent='Replay building · statistics show full run';
  representatives.forEach(({bi,value},i)=>{
   const bin=result.histogram[bi],x=plotX(value),h=bin.count/maxCount*(dimensions.bottom-dimensions.top),y=dimensions.bottom-h*(++scheduled[bi]/quotas[bi]),dot=document.createElementNS('http://www.w3.org/2000/svg',i%4===0?'rect':'circle');
   if(i%4===0){dot.setAttribute('x',x-2.8);dot.setAttribute('y',y-2.8);dot.setAttribute('width','5.6');dot.setAttribute('height','5.6');dot.setAttribute('rx','1')}else{dot.setAttribute('cx',x);dot.setAttribute('cy',y);dot.setAttribute('r','2.5')}dot.setAttribute('fill',palette().signal);dot.style.opacity='0';group.appendChild(dot);
   if(typeof dot.animate!=='function'){dot.remove();return}const a=dot.animate([{opacity:0,transform:`translateY(${-y+18}px)`},{opacity:.9,offset:.1,transform:`translateY(${-y+18}px)`},{opacity:.85,offset:.94,transform:'translateY(0)'},{opacity:0,transform:'translateY(2px)'}],{duration:1350,delay:i*19,easing:'cubic-bezier(.35,0,.8,.6)',fill:'none'});animations.push(a);a.onfinish=()=>{dot.remove();const nextHeight=h*(++arrivals[bi]/quotas[bi]),bar=barFinals[bi]?.node;bar?.setAttribute('height',nextHeight);bar?.setAttribute('y',dimensions.bottom-nextHeight);animations=animations.filter(x=>x!==a);if(!animations.length)finish()};
  });
  if(!animations.length)finish();
  if(animations.length){find('#mc-skip').hidden=false;find('#mc-play').textContent='Pause the flow Ⅱ';find('#mc-play').setAttribute('aria-pressed','true')}
 }
 shell();try{result=simulateCurrent(snapshot,draft,config);paint();if(typeof IntersectionObserver!=='function')play()}catch(e){find('#mc-output').innerHTML=`<div class="error">${esc(e.message)}</div>`}
 const mq=signal();listen(mq,'change',()=>{if(mq.matches)finish();const b=find('#mc-play');if(b){b.disabled=mq.matches;b.textContent=mq.matches?'Reduced motion · static view':'Replay the flow ↻'}});listen(document,'visibilitychange',()=>{if(document.hidden)finish()});listen(globalThis,'valuation:theme-change',()=>{if(result?.accepted)paint()});listen(globalThis,'valuation:tab-change',e=>{if(e.detail!=='current')finish()});
 if(typeof IntersectionObserver==='function'){const observer=new IntersectionObserver(entries=>{if(entries[0].isIntersecting&&!viewed){viewed=true;play()}else if(!entries[0].isIntersecting)finish()},{threshold:.05});observer.observe(root);cleanups.push(()=>observer.disconnect())}
 return destroy;
}
